ValidationRule.errorConditionFormula:
OR(
    AND(
        ISPICKVAL(Relacionado_a_entrega__c, "Projeto"),
            OR(
                AND(
                    ISBLANK(Relacionado_ao_Projeto__c),
                    NOT(ISBLANK(Numero_do_Contrato__c))
                ),
                AND(
                    NOT(ISBLANK(Relacionado_ao_Projeto__c)),
                    NOT(ISBLANK(Numero_do_Contrato__c))
                )
            )
    ),
    AND(
        ISPICKVAL(Relacionado_a_entrega__c, "Projeto"),
        ISBLANK(Relacionado_ao_Projeto__c)
    )
)
